const payload = items[0].json;
const normalized = {
  case_type: (payload.case_type || '').toUpperCase(),
  checklist: payload.checklist || [],
  data: payload.data || {}
};
const crypto = require('crypto');
const idempotency_key = crypto.createHash('sha256').update(JSON.stringify(normalized)).digest('hex');
const correlation_id = payload.correlation_id || crypto.randomUUID();
return [{ json: { normalized, idempotency_key, correlation_id } }];

const normalized = $json.normalized || $items("Normalize + Hash")[0].json.normalized;
const ruleset = 'v1';
const errors = [];
const requiredByType = {
  PIDUM: ['suspect_name', 'pasal'],
  TIPIKOR: ['suspect_name', 'nilai_kerugian'],
  PERDATA: ['penggugat', 'tergugat'],
  PHI: ['penggugat', 'perusahaan'],
  TILANG: ['vehicle_plate', 'violation_code']
};
const req = requiredByType[normalized.case_type] || [];
for (const field of req) {
  if (!normalized.data[field]) errors.push({ field, code: 'REQUIRED' });
}
return [{ json: { ruleset, errors, is_valid: errors.length === 0 } }];

const validation = $items("Validate Ruleset")[0].json;
const checklist = $items("Normalize + Hash")[0].json.normalized.checklist || [];
const status = validation.is_valid && checklist.length > 0 ? 'DRAFT' : 'TERTAHAN';
return [{ json: { status, errors: validation.errors } }];
